#!/usr/bin/env python3
"""
Round 178b (culprits), 5 October 2026. Needs round 177b.

Colour squares on each layer's own line, and working.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 178b (5 October)\n\nNeeds round 177b (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Owner: the colour squares did nothing, and sat below the menu that\n  unfolds under a ticked layer. rowTint itself worked when tried in a\n  browser; the squares lived in .row-tools, each with its own listener.\n- Now each layer's square sits on the layer's own line (label[data-tint-row],\n  before its fold arrow), shown only while it is ticked (:has); headings keep\n  theirs on the heading line. One capturing listener on the layers box\n  serves every square (input, change, click), so rows added or redrawn later\n  work too; addRowTools calls tintTools each time it runs.\n- tintFor: the first paint hook gives a tinted row's layers their chosen\n  colour whenever anything else repaints them (themes, the colour wheel,\n  keys). ROW_TINT and TINT_ORIG are var, for the hook's early calls.\n- Checked in Chromium with a stand-in row: the square shows on the line,\n  colours the layer, keeps it through a repaint, hides when unticked; As\n  drawn restores; a heading's square colours its ticked layers and sets\n  their squares.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round178b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 177b" not in h.read_text(encoding="utf-8"):
        sys.exit("round178b: round 177b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round178b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round178b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round178b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
